    "ce": "# Align by symbol — exported by Manim Formula Editor for ManimCE 0.22.\n# Render at 1920×1080, 60 fps:\n#     manim -r 1920,1080 --fps 60 AlignBySymbol.py AlignBySymbol\n# Every play and wait lasts a whole number of frames at 60 fps, so the video has\n# exactly 600 frames, like the editor's video export.\nfrom manim import *\n\n\ndef _glyphs(tex, layout):\n    \"\"\"The glyphs of `tex` in the editor's order. That order (MathJax's, or another\n    template's) can differ from Manim's, so the glyphs are matched by position: `layout`\n    holds each glyph's (x, y, width, height) relative to the formula centre, divided by the\n    formula height, and every real glyph is assigned to one entry with the least total\n    distance. Entries without a counterpart get an empty VMobject.\"\"\"\n    from scipy.optimize import linear_sum_assignment\n\n    real = tex.family_members_with_points()\n    glyphs = [VMobject() for _ in layout]\n    if len(real) != len(layout):\n        print(f\"Warning: Manim made {len(real)} glyphs of a formula the editor split into \"\n              f\"{len(layout)}; unmatched glyphs are not animated.\")\n    if not real or not layout:\n        return glyphs  # nothing to match (a formula without ink, such as \\quad)\n    centre, height = tex.get_center(), tex.get_height()\n    if height < 1e-6:\n        height = 1.0  # a flat mobject (a rule): the editor's layout is divided by 1 then too\n    have = np.array([\n        [*((g.get_center() - centre)[:2] / height), g.get_width() / height, g.get_height() / height]\n        for g in real\n    ])\n    want = np.array(layout, dtype=float)\n    cost = np.linalg.norm(want[:, None, :] - have[None, :, :], axis=2)\n    for i, j in zip(*linear_sum_assignment(cost)):\n        glyphs[i] = real[j]\n    return glyphs\n\n\nclass AlignBySymbol(Scene):\n    def construct(self):\n        self.camera.background_color = \"#070B15\"\n\n        # l1: 2x + 3 = 11\n        l1 = MathTex(r\"2x + 3 = 11\", font_size=72)\n        l1_g = _glyphs(l1, [\n            (-3.0789, 0.0548, 0.5334, 0.8904), (-2.3717, -0.1023, 0.6511, 0.6056), (-1.1622, -0.0555, 0.8904, 0.889), (-0.0115, 0.0394, 0.5548, 0.9184),\n            (1.2148, -0.0561, 0.8904, 0.3128), (2.4472, 0.0548, 0.4599, 0.8904), (3.1156, 0.0548, 0.4599, 0.8904),\n        ])\n        l1.move_to([0, 2.4, 0])\n        l1.set_z_index(3)\n\n        # l2: 2x = 11 - 3\n        l2 = MathTex(r\"2x = 11 - 3\", font_size=72)\n        l2_g = _glyphs(l2, [\n            (-3.3692, 0.016, 0.5799, 0.968), (-2.6003, -0.1548, 0.7078, 0.6584), (-1.2045, -0.1047, 0.968, 0.3401), (0.1353, 0.016, 0.5, 0.968),\n            (0.8621, 0.016, 0.5, 0.968), (2.1065, -0.1047, 0.8866, 0.0581), (3.3576, -0.0007, 0.6032, 0.9985),\n        ])\n        l2.move_to([1.305969, 0.8, 0])\n        l2.set_z_index(2)\n\n        # l3: 2x = 8\n        l3 = MathTex(r\"2x = 8\", font_size=72)\n        l3_g = _glyphs(l3, [\n            (-1.7541, 0.016, 0.5799, 0.968), (-0.9852, -0.1548, 0.7078, 0.6584), (0.4106, -0.1047, 0.968, 0.3401), (1.7432, 0, 0.6017, 1),\n        ])\n        l3.move_to([0.470702, -0.8, 0])\n        l3.set_z_index(1)\n\n        # l4: x = 4\n        l4 = MathTex(r\"x = 4\", font_size=72)\n        l4_g = _glyphs(l4, [\n            (-1.3478, -0.1708, 0.7078, 0.6584), (0.048, -0.1206, 0.968, 0.3401), (1.3798, 0.008, 0.6439, 0.984),\n        ])\n        l4.move_to([0.658246, -2.4, 0])\n\n        # 0 s – 1 s: l1 write\n        self.play(Write(VGroup(*l1_g[:])), run_time=1)\n        # 1 s – 1.2 s\n        self.wait(0.2)\n        # 1.2 s – 2.2 s: l2 write\n        self.play(Write(VGroup(*l2_g[:])), run_time=1)\n        # 2.2 s – 2.4 s\n        self.wait(0.2)\n        # 2.4 s – 3.4 s: l3 write\n        self.play(Write(VGroup(*l3_g[:])), run_time=1)\n        # 3.4 s – 3.6 s\n        self.wait(0.2)\n        # 3.6 s – 4.6 s: l4 write\n        self.play(Write(VGroup(*l4_g[:])), run_time=1)\n        # 4.6 s – 10 s\n        self.wait(5.4)\n",
    "gl": "# Align by symbol — exported by Manim Formula Editor for ManimGL 1.7.\n# Render at 1920×1080, 60 fps:\n#     manimgl AlignBySymbol.py AlignBySymbol -w -r 1920x1080 --fps 60\n# Every play and wait lasts a whole number of frames at 60 fps, so the video has\n# exactly 600 frames, like the editor's video export.\nfrom manimlib import *\n\n\ndef _glyphs(tex, layout):\n    \"\"\"The glyphs of `tex` in the editor's order. That order (MathJax's, or another\n    template's) can differ from Manim's, so the glyphs are matched by position: `layout`\n    holds each glyph's (x, y, width, height) relative to the formula centre, divided by the\n    formula height, and every real glyph is assigned to one entry with the least total\n    distance. Entries without a counterpart get an empty VMobject.\"\"\"\n    from scipy.optimize import linear_sum_assignment\n\n    real = tex.family_members_with_points()\n    glyphs = [VMobject() for _ in layout]\n    if len(real) != len(layout):\n        print(f\"Warning: Manim made {len(real)} glyphs of a formula the editor split into \"\n              f\"{len(layout)}; unmatched glyphs are not animated.\")\n    if not real or not layout:\n        return glyphs  # nothing to match (a formula without ink, such as \\quad)\n    centre, height = tex.get_center(), tex.get_height()\n    if height < 1e-6:\n        height = 1.0  # a flat mobject (a rule): the editor's layout is divided by 1 then too\n    have = np.array([\n        [*((g.get_center() - centre)[:2] / height), g.get_width() / height, g.get_height() / height]\n        for g in real\n    ])\n    want = np.array(layout, dtype=float)\n    cost = np.linalg.norm(want[:, None, :] - have[None, :, :], axis=2)\n    for i, j in zip(*linear_sum_assignment(cost)):\n        glyphs[i] = real[j]\n    return glyphs\n\n\nclass AlignBySymbol(Scene):\n    default_camera_config = dict(background_color=\"#070B15\")\n\n    def construct(self):\n\n        # l1: 2x + 3 = 11\n        l1 = Tex(r\"2x + 3 = 11\", font_size=74.2416)\n        l1_g = _glyphs(l1, [\n            (-3.0789, 0.0548, 0.5334, 0.8904), (-2.3717, -0.1023, 0.6511, 0.6056), (-1.1622, -0.0555, 0.8904, 0.889), (-0.0115, 0.0394, 0.5548, 0.9184),\n            (1.2148, -0.0561, 0.8904, 0.3128), (2.4472, 0.0548, 0.4599, 0.8904), (3.1156, 0.0548, 0.4599, 0.8904),\n        ])\n        l1.move_to([0, 2.4, 0])\n        l1.set_z_index(3)\n\n        # l2: 2x = 11 - 3\n        l2 = Tex(r\"2x = 11 - 3\", font_size=74.2416)\n        l2_g = _glyphs(l2, [\n            (-3.3692, 0.016, 0.5799, 0.968), (-2.6003, -0.1548, 0.7078, 0.6584), (-1.2045, -0.1047, 0.968, 0.3401), (0.1353, 0.016, 0.5, 0.968),\n            (0.8621, 0.016, 0.5, 0.968), (2.1065, -0.1047, 0.8866, 0.0581), (3.3576, -0.0007, 0.6032, 0.9985),\n        ])\n        l2.move_to([1.305969, 0.8, 0])\n        l2.set_z_index(2)\n\n        # l3: 2x = 8\n        l3 = Tex(r\"2x = 8\", font_size=74.2416)\n        l3_g = _glyphs(l3, [\n            (-1.7541, 0.016, 0.5799, 0.968), (-0.9852, -0.1548, 0.7078, 0.6584), (0.4106, -0.1047, 0.968, 0.3401), (1.7432, 0, 0.6017, 1),\n        ])\n        l3.move_to([0.470702, -0.8, 0])\n        l3.set_z_index(1)\n\n        # l4: x = 4\n        l4 = Tex(r\"x = 4\", font_size=74.2416)\n        l4_g = _glyphs(l4, [\n            (-1.3478, -0.1708, 0.7078, 0.6584), (0.048, -0.1206, 0.968, 0.3401), (1.3798, 0.008, 0.6439, 0.984),\n        ])\n        l4.move_to([0.658246, -2.4, 0])\n\n        # 0 s – 1 s: l1 write\n        self.play(Write(VGroup(*l1_g[:]), stroke_color=\"#FFFFFF\"), run_time=1)\n        # 1 s – 1.2 s\n        self.wait(0.2)\n        # 1.2 s – 2.2 s: l2 write\n        self.play(Write(VGroup(*l2_g[:]), stroke_color=\"#FFFFFF\"), run_time=1)\n        # 2.2 s – 2.4 s\n        self.wait(0.2)\n        # 2.4 s – 3.4 s: l3 write\n        self.play(Write(VGroup(*l3_g[:]), stroke_color=\"#FFFFFF\"), run_time=1)\n        # 3.4 s – 3.6 s\n        self.wait(0.2)\n        # 3.6 s – 4.6 s: l4 write\n        self.play(Write(VGroup(*l4_g[:]), stroke_color=\"#FFFFFF\"), run_time=1)\n        # 4.6 s – 10 s\n        self.wait(5.4)\n"
